import json

# Write transform function
transform_code = '''
def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = 8  # filler color

    # Find bar cells (9) and mark position
    bar_cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 9}
    # Find existing dot (4)
    dot_pos = None
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 4:
                dot_pos = (r, c)
                break
        if dot_pos:
            break

    # Output with default filler
    output = [[bg] * w for _ in range(h)]

    # Preserve barriers
    for r, c in bar_cells:
        output[r][c] = 9

    # If dot exists, preserve it
    if dot_pos:
        dr, dc = dot_pos
        output[dr][dc] = 4

    # Add stub line from dot toward nearest bar
    # Dot is at (13, 6), right bar at col 22, so stub goes right
    if dot_pos:
        dr, dc = dot_pos
        # Check which bar is closer
        left_bar = any(c == 0 for r, c in bar_cells)
        right_bar = any(c == w - 1 for r, c in bar_cells)
        if right_bar:
            for c in range(dc + 1, w - 1):  # stop before right bar
                if (dr, c) not in bar_cells:
                    output[dr][c] = bg
        if left_bar:
            for c in range(dc):
                if (dr, c) not in bar_cells:
                    output[dr][c] = bg

    # Add mirror fill
    # Mirror row is between bar ends: left bar ends at row 4, right bar starts at row 9
    # Mirror at row 6
    if left_bar and right_bar:
        left_end = max(r for r, c in bar_cells if c == 0)
        right_start = min(r for r, c in bar_cells if c == w - 1)
        mirror_row = (left_end + right_start) // 2
        for c in range(w):
            if (mirror_row, c) not in bar_cells:
                output[mirror_row][c] = bg

    return output
'''

